// ---- the provisional profile pins (validator-registry design section 3.3.4)
// ----------------------
//
// VR's immutable per-call caps and its own step allowances, as `src/vr/VRShared.sol` declares them
// (all provisional there). A module's caps are min(its gasBounds, these), so a budget at these caps
// covers every module VR can activate.
const CAP_ELECT: u64 = 4_000_000;
const CAP_OUTPUT: u64 = 1_000_000;
const CAP_RECORD: u64 = 1_500_000;
const CAP_RESOLVED: u64 = 500_000;
const CAP_ATTACH: u64 = 3_000_000;
const CAP_DETACH: u64 = 500_000;
const CAP_ADOPT: u64 = 1_000_000;
const ELECT_VR_GAS: u64 = 2_600_000;
const VOID_VR_GAS: u64 = 40_000;
const INNER_SLACK: u64 = 5_000;
const OUTER_RESERVE: u64 = 60_000;
/// VR's own work in the worst Boundary (16 installed, 15 activated, the switch and a holder entry):
/// forge `test/vr/VRGas.t.sol` measures 2,221,076 with cheap callbacks.
const G_BOUNDARY_VR: u64 = 2_300_000;

/// The inner call's requirement for a cap (`VRShared._inner`).
const fn inner(cap: u64) -> u64 {
    cap + cap / 63 + INNER_SLACK
}

/// What a contained step requires of `gasleft()` before it calls (`VRShared._contained`).
const fn need(budget: u64) -> u64 {
    budget + budget / 63 + OUTER_RESERVE
}

/// The pin of a measured or derived requirement: `ceil(m * 5 / 4)`, the rule of bft-core
/// `b1state.PinElectGas`.
const fn pin(m: u64) -> u64 {
    (m * 5).div_ceil(4)
}

/// A contained void step at `cap`.
const fn void_need(cap: u64) -> u64 {
    need(inner(cap) + VOID_VR_GAS)
}

/// The contained elect step at the given module caps.
const fn elect_need(cap_elect: u64, cap_output: u64) -> u64 {
    need(inner(cap_elect) + inner(cap_output) + ELECT_VR_GAS)
}

const fn max(a: u64, b: u64) -> u64 {
    if a > b {
        a
    } else {
        b
    }
}

/// The analytical elect requirement: the contained elect step at VR's caps (without VR's gate,
/// watchdogs and context before the step).
const ELECT_ANALYTICAL: u64 = elect_need(CAP_ELECT, CAP_OUTPUT);
/// The complete elect requirement measured at VR's maximum accepted caps: the smallest `ElectGas`
/// at which the `elect-max` scenario (16 members, 16 bound changes, 64 KiB of payloads, the module
/// burning both caps) still reserves, pre-step work and outer completion included. The gas tests
/// fail if a scenario needs more.
const ELECT_REQUIREMENT: u64 = 7_981_443;
/// Provisional `ElectGas`: the larger requirement, with the rounded-up 5/4 margin.
const ELECT_GAS: u64 = pin(max(ELECT_ANALYTICAL, ELECT_REQUIREMENT));

/// The analytical record requirement of design 3.3.4: the worst record, a Boundary that installs
/// 16 members, activates the bound changes and switches the pointer (onResolved, adoption, the old
/// module's onRecords share, detach and attach, each contained at VR's caps), plus VR's own work
/// as forge measured it with small payloads. It underestimates VR's own work with the largest
/// legal payloads (see `RECORD_REQUIREMENT`).
const RECORD_ANALYTICAL: u64 = G_BOUNDARY_VR +
    void_need(CAP_RESOLVED) +
    void_need(CAP_ADOPT) +
    void_need(CAP_RECORD) +
    void_need(CAP_DETACH) +
    void_need(CAP_ATTACH);
/// The complete per-record requirement measured at VR's maximum accepted caps: the smallest
/// records budget at which the `switch-max` Boundary, delivered alone, still applies as forge
/// computed (16 installed, 15 changes activated with 64 KiB of payloads, every callback burning its
/// maximum cap, the 16,256-byte initData in the attach context). The gas tests fail if a scenario
/// needs more per record.
const RECORD_REQUIREMENT: u64 = 17_977_590;
/// Provisional `HookRecordGas`: the larger requirement, with the rounded-up 5/4 margin.
const HOOK_RECORD_GAS: u64 = pin(max(RECORD_ANALYTICAL, RECORD_REQUIREMENT));
// ---- the VR batch pins (VT-14; astra urethhook r2; bft-core b1state CheckVRHookGas) -----------
//
// A VR profile does not price records one by one. Its `HookRecordGas` is the amortized encoding of
// a FIXED allowance for one H-record records call: ceil(5/4 x M_H) with M_H = R_H + B (raised by
// any combined fixture that needs more). It rests on VR's single-live-output invariant: one records
// call finalizes at most one nonterminal output and switches the pointer at most once, and the two
// onRecords segments of a switch carry at most H records together. ureth's hook already hands
// `applyRootRecords` the whole remaining envelope (H x HookRecordGas), whatever the call applies.

/// `R_32`: the smallest records reservation of the full H = 32 delivery at the maximum record cap
/// (`batch32-max`).
const BATCH_REQUIREMENT: u64 = 52_262_738;
/// `M_32 = R_32 + B`, B the complete switching Boundary delivered alone (`RECORD_REQUIREMENT`).
const BATCH_ALLOWANCE_REQUIREMENT: u64 = BATCH_REQUIREMENT + RECORD_REQUIREMENT;
/// The VR profile's `HookRecordGas`: `ceil(ceil(5/4 x M_32) / 32)`.
const VR_HOOK_RECORD_GAS: u64 = pin(BATCH_ALLOWANCE_REQUIREMENT).div_ceil(32);
/// The combined fixtures: the switching output's Ack, 30 ordinary records and its Boundary in one
/// H = 32 call, the switch at the start, middle or end (permanent acceptance cases).
const COMBINED: [&str; 3] = ["mixed-first", "mixed-middle", "mixed-last"];
/// The legal bounds the worst cases are built at (schema v1; `VRHookState.t.sol`): 16 members, 16
/// bound changes with 64 KiB of payloads, one change up to 16 KiB, 32 pending changes, 64
/// activations. bft-core `b1state.VRLimits` refuses a measurement at other ceilings.
const CEILINGS: [(&str, u64); 6] = [
    ("committee", 16),
    ("boundChanges", 16),
    ("boundPayload", 64 * 1024),
    ("changePayload", 16 * 1024),
    ("pendingChanges", 32),
    ("activations", 64),
];

/// Ordinary capacity added to the block, so the public transactions of a scenario fit (a funded
/// `publish` needs about 3.7 M of `gasleft()` for its contained step, whatever it spends).
const ORDINARY_EXTRA: u64 = 40_000_000;
/// The funded account of the signed genesis (private key 1).
const SENDER_KEY: B256 = B256::with_last_byte(1);

// ---- the fixture ------------------------------------------------------------------------------

type Slots = BTreeMap<U256, U256>;

struct Account {
    role: String,
    address: Address,
    code: Bytes,
}

#[derive(Debug)]
struct Expect {
    applied: u64,
    outcome: u8,
    health: u8,
    cursor: u64,
    open_output: B256,
    last_acked: B256,
    active_module: Address,
}

struct PublicTx {
    to: Address,
    data: Bytes,
    gas_limit: u64,
    success: bool,
}

struct Scenario {
    name: String,
    /// The `H_records` the profile pins (32 throughout).
    h: u32,
    progress: u64,
    uc_time: u64,
    records: Vec<RecordEntry>,
    pre: BTreeMap<Address, Slots>,
    post: BTreeMap<Address, Slots>,
    /// The state after the hooks alone (before the public transactions); `post` without any.
    after_hooks: BTreeMap<Address, Slots>,
    txs: Vec<PublicTx>,
    expect: Expect,
}

struct Fixture {
    origin: B256,
    accounts: Vec<Account>,
    scenarios: Vec<Scenario>,
}

fn word(v: &serde_json::Value) -> U256 {
    U256::from_str_radix(v.as_str().unwrap().trim_start_matches("0x"), 16).unwrap()
}

fn slots(v: &serde_json::Value) -> BTreeMap<Address, Slots> {
    v.as_object()
        .unwrap()
        .iter()
        .map(|(a, s)| {
            let s = s.as_object().unwrap().iter().map(|(k, v)| (word(&k.as_str().into()), word(v)));
            (a.parse().unwrap(), s.collect())
        })
        .collect()
}

fn fixture() -> &'static Fixture {
    static F: OnceLock<Fixture> = OnceLock::new();
    F.get_or_init(|| {
        let f: serde_json::Value = serde_json::from_str(FIXTURE).unwrap();
        assert_eq!(f["format"], "unicity-vr-hook-state-v1");
        assert_eq!(f["chainId"], 1337, "the state was produced on the chain the world runs");
        let accounts = f["accounts"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(role, a)| {
                let code: Bytes = a["code"].as_str().unwrap().parse().unwrap();
                assert_eq!(
                    keccak256(&code),
                    a["codeHash"].as_str().unwrap().parse::<B256>().unwrap(),
                    "{role}"
                );
                Account {
                    role: role.clone(),
                    address: a["address"].as_str().unwrap().parse().unwrap(),
                    code,
                }
            })
            .collect();
        let scenarios = f["scenarios"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(name, s)| {
                assert_eq!(
                    s["blockNumber"], 1,
                    "{name}: forge ran the hooks at the ureth block number"
                );
                let mut records: Vec<RecordEntry> = Vec::new();
                for r in s["records"].as_array().unwrap() {
                    let predecessor = records.last().map_or(B256::ZERO, |e| e.record_id);
                    let entry = testing::record_entry(
                        r["index"].as_u64().unwrap(),
                        predecessor,
                        r["kind"].as_u64().unwrap() as u8,
                        r["progress"].as_u64().unwrap(),
                        r["ucTime"].as_u64().unwrap(),
                        r["data"].as_str().unwrap().parse::<Bytes>().unwrap().to_vec(),
                    );
                    assert_eq!(
                        entry.record_id,
                        r["recordId"].as_str().unwrap().parse::<B256>().unwrap(),
                        "{name}: the identifier forge computed is the one this crate computes"
                    );
                    assert_eq!(
                        entry.predecessor,
                        r["predecessor"].as_str().unwrap().parse::<B256>().unwrap()
                    );
                    records.push(entry);
                }
                let pre = slots(&s["pre"]);
                let apply = |changes: &serde_json::Value| {
                    let mut out = pre.clone();
                    for (address, changed) in slots(changes) {
                        let account = out.entry(address).or_default();
                        for (k, v) in changed {
                            if v.is_zero() {
                                account.remove(&k);
                            } else {
                                account.insert(k, v);
                            }
                        }
                    }
                    out.retain(|_, s| !s.is_empty());
                    out
                };
                let post = apply(&s["changed"]);
                let after_hooks = if s.get("changedByHooks").is_some() {
                    apply(&s["changedByHooks"])
                } else {
                    post.clone()
                };
                let txs = s
                    .get("txs")
                    .and_then(|t| t.as_array())
                    .map(|t| {
                        t.iter()
                            .map(|t| PublicTx {
                                to: t["to"].as_str().unwrap().parse().unwrap(),
                                data: t["data"].as_str().unwrap().parse().unwrap(),
                                gas_limit: t["gasLimit"].as_u64().unwrap(),
                                success: t["success"].as_bool().unwrap(),
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                let e = &s["expect"];
                Scenario {
                    name: name.clone(),
                    h: s["h"].as_u64().unwrap() as u32,
                    progress: s["progress"].as_u64().unwrap(),
                    uc_time: s["ucTime"].as_u64().unwrap(),
                    records,
                    pre,
                    post,
                    after_hooks,
                    txs,
                    expect: Expect {
                        applied: e["applied"].as_u64().unwrap(),
                        outcome: e["outcome"].as_u64().unwrap() as u8,
                        health: e["health"].as_u64().unwrap() as u8,
                        cursor: e["cursor"].as_u64().unwrap(),
                        open_output: e["openOutput"].as_str().unwrap().parse().unwrap(),
                        last_acked: e["lastAcked"].as_str().unwrap().parse().unwrap(),
                        active_module: e["activeModule"].as_str().unwrap().parse().unwrap(),
                    },
                }
            })
            .collect();
        Fixture { origin: f["origin"].as_str().unwrap().parse().unwrap(), accounts, scenarios }
    })
}

fn scenario(name: &str) -> &'static Scenario {
    fixture().scenarios.iter().find(|s| s.name == name).unwrap_or_else(|| panic!("no {name}"))
}

fn account(role: &str) -> Address {
    fixture().accounts.iter().find(|a| a.role == role).unwrap().address
}

// ---- the world --------------------------------------------------------------------------------

/// Block 1 over the signed genesis with the scenario's accounts allocated, importing the
/// scenario's records at its progress and UC time.
struct World {
    txs: Vec<Recovered<TransactionSigned>>,
    provider: FixtureProvider,
    parent: SealedHeader<alloy_consensus::Header>,
    root: RootInputV2,
    chain_spec: Arc<ChainSpec>,
    import: Bytes,
    update: Bytes,
}

impl World {
    fn new(s: &Scenario) -> Self {
        let genesis: Genesis =
            serde_json::from_str(include_str!("../testdata/signed-beacon-genesis.json")).unwrap();
        let chain_spec = Arc::new(ChainSpec::from_genesis(genesis));
        let parent = SealedHeader::new(chain_spec.genesis_header().clone(), genesis_hash());
        let mut provider = FixtureProvider::signed_genesis();
        provider.set_block_hash(0, genesis_hash());
        for a in &fixture().accounts {
            let storage: Vec<(U256, U256)> =
                s.pre.get(&a.address).into_iter().flatten().map(|(k, v)| (*k, *v)).collect();
            provider.insert_contract(a.address, a.code.clone(), U256::ZERO, &storage);
        }
        let import: Bytes = RecordImport {
            progress: s.progress,
            uc_time: s.uc_time,
            target_count: s.records.len() as u64,
            target_tip: s.records.last().map_or(B256::ZERO, |e| e.record_id),
            entries: s.records.clone(),
        }
        .to_bytes()
        .into();
        let mut root = input(1, 1, genesis_hash());
        let update = testing::seal_with_import(&mut root, 0, GENESIS_TAIL, &import);
        assert_eq!(
            root.origin_identity().unwrap(),
            fixture().origin,
            "forge elected under the origin identity this block carries"
        );
        let txs = s
            .txs
            .iter()
            .enumerate()
            .map(|(nonce, t)| {
                let tx = Transaction::Legacy(TxLegacy {
                    chain_id: Some(1337),
                    nonce: nonce as u64,
                    gas_price: 10_000_000_000,
                    gas_limit: t.gas_limit,
                    to: TxKind::Call(t.to),
                    value: U256::ZERO,
                    input: t.data.clone(),
                });
                let signature = sign_message(SENDER_KEY, tx.signature_hash()).unwrap();
                TransactionSigned::new_unhashed(tx, signature).try_into_recovered().unwrap()
            })
            .collect();
        Self { txs, provider, parent, root, chain_spec, import, update }
    }

    /// The block profile whose system reservation is the base one plus exactly the hook envelope.
    fn profile(&self, hook: &RecordsHook) -> BlockProfile {
        let base = profile();
        let envelope = hook.envelope_gas().unwrap();
        BlockProfile {
            system_gas: base.system_gas + envelope,
            max_gas: base.max_gas + envelope + ORDINARY_EXTRA,
            ..base
        }
    }

    fn attributes(&self, hook: &RecordsHook) -> NextBlockEnvAttributes {
        NextBlockEnvAttributes {
            timestamp: derive_timestamp(self.root.origin.reference_time, self.parent.timestamp)
                .unwrap(),
            suggested_fee_recipient: FEE_COLLECTOR,
            prev_randao: derive_prev_randao(
                self.root.origin.root_round,
                self.root.authorized_round,
            ),
            gas_limit: self.profile(hook).max_gas,
            parent_beacon_block_root: Some(derive_beacon_root(
                self.root.origin.root_round,
                self.root.authorized_round,
            )),
            withdrawals: Some(Default::default()),
            extra_data: self.root.input_commitment().unwrap().to_vec().into(),
            slot_number: None,
        }
    }

    fn config(&self, hook: RecordsHook) -> UnicityEvmConfig {
        let mut job =
            B1Job { context: context(), update: self.update.clone(), records: self.import.clone() };
        job.context.hook = hook;
        let bound = Arc::new(
            BoundExecutionInput::from_validated_genesis(
                Arc::new(self.root.clone()),
                job,
                self.profile(&hook),
                &self.parent,
                genesis_hash(),
                FEE_COLLECTOR,
            )
            .unwrap(),
        );
        UnicityEvmConfig::new(
            unicity_eth_config(self.chain_spec.clone(), &testing::b1_context()),
            bound,
        )
    }

    /// Builds block 1 through the real block path, with the scenario's public transactions after
    /// the hooks, and returns it with the state after it.
    fn build(&self, hook: RecordsHook) -> Result<(CompletedBuild, FixtureProvider), String> {
        self.build_with(hook, self.txs.clone())
    }

    fn build_with(
        &self,
        hook: RecordsHook,
        txs: Vec<Recovered<TransactionSigned>>,
    ) -> Result<(CompletedBuild, FixtureProvider), String> {
        let config = self.config(hook);
        let mut state =
            State::builder().with_database(self.provider.clone()).with_bundle_update().build();
        let built = build_complete(
            &config,
            &self.parent,
            self.attributes(&hook),
            &mut state,
            self.provider.clone(),
            txs,
        )
        .map_err(|e| e.to_string())?;
        let mut after = self.provider.clone();
        after.apply_bundle(&state.bundle_state);
        Ok((built, after))
    }

    /// The state the hooks start from: the block built without them (the records imported, finalize
    /// and EIP-4788 done). The registry's words do not depend on the hook (`block_adapter.rs`).
    fn before_hooks(&self) -> (FixtureProvider, HookEnv) {
        let (built, before) = self.build_with(RecordsHook::default(), vec![]).unwrap();
        let header = built.outcome.block.header();
        (before, HookEnv::at(1337, header.number, header.timestamp))
    }
}

/// ureth's hook (`run_hooks`, the function the block executor calls) run directly on `before`
/// within `budget`, returning what it reported and the state after it.
fn hooks_on(
    before: &FixtureProvider,
    env: &HookEnv,
    hook: &RecordsHook,
    budget: u64,
) -> Result<(HookOutcome, FixtureProvider), String> {
    let mut state = State::builder().with_database(before.clone()).with_bundle_update().build();
    let outcome =
        run_hooks(&mut state, hook, env, fixture().origin, budget).map_err(|e| format!("{e:?}"))?;
    state.merge_transitions(BundleRetention::PlainState);
    let mut after = before.clone();
    after.apply_bundle(&state.take_bundle());
    Ok((outcome, after))
}

/// The pinned hook of a scenario: VR as the custody and the election, the fixture's H, at the
/// provisional pins.
const fn pinned(s: &Scenario) -> RecordsHook {
    RecordsHook {
        custody: VR,
        h_records: s.h,
        record_gas: HOOK_RECORD_GAS,
        election: VR,
        elect_gas: ELECT_GAS,
    }
}

/// The slot-for-slot differences between ureth's state after the block and forge's.
fn diff(after: &FixtureProvider, s: &Scenario) -> Vec<String> {
    diff_from(after, &s.post)
}

/// The same after the hooks alone (the direct runs, before any public transaction).
fn diff_hooks(after: &FixtureProvider, s: &Scenario) -> Vec<String> {
    diff_from(after, &s.after_hooks)
}

/// The slot-for-slot differences between `after` and `want` on every fixture account.
fn diff_from(after: &FixtureProvider, want_all: &BTreeMap<Address, Slots>) -> Vec<String> {
    let mut out = Vec::new();
    for a in &fixture().accounts {
        let got = after.storage_of(a.address);
        let empty = Slots::new();
        let want = want_all.get(&a.address).unwrap_or(&empty);
        for k in got.keys().chain(want.keys()).collect::<std::collections::BTreeSet<_>>() {
            if got.get(k) != want.get(k) {
                out.push(format!(
                    "{} slot {k:#x}: ureth {:?} forge {:?}",
                    a.role,
                    got.get(k),
                    want.get(k)
                ));
            }
        }
    }
    out
}

// ---- views on the state after the block --------------------------------------------------------

sol! {
    function health() external view returns (uint8);
    function recordCursor() external view returns (uint64);
    function openOutput() external view returns (bytes32);
    function lastAcked() external view returns (bytes32);
    function retired(uint8 holder, uint64 id, uint64 generation) external view returns (bool);
    function holderCount() external view returns (uint8);
    function activeModule() external view returns (address module);
    function output(bytes32 resultId) external view returns (uint8 state);
    // MockModule (test/vr/VRMocks.sol)
    function logLength() external view returns (uint256);
    function log(uint256 i) external view returns (string);
    function attachMembers() external view returns (uint256);
    function attachPrevious() external view returns (address);
    function reentryAttempts() external view returns (uint256);
    function reentryRefusals() external view returns (uint256);
    function reentryErrors(uint256 k) external view returns (bytes4);
    // PublishDriver (test/vr/VRHookState.t.sol)
    function pendingSeen() external view returns (uint256);
    function shortRefused() external view returns (bool);
    function published() external view returns (bool);
}

/// One read-only call of VR against `state`, from the system caller, discarded.
fn view(state: &FixtureProvider, data: Vec<u8>) -> Bytes {
    view_at(state, VR, data)
}

/// The decoded answer of a read-only call of `to`.
fn call<C: SolCall>(state: &FixtureProvider, to: Address, c: C) -> C::Return {
    C::abi_decode_returns(&view_at(state, to, c.abi_encode())).unwrap()
}

/// The module's step log, in order.
fn module_log(state: &FixtureProvider, module: Address) -> Vec<String> {
    let n = call(state, module, logLengthCall {});
    (0..n.to::<u64>()).map(|i| call(state, module, logCall { i: U256::from(i) })).collect()
}

/// One read-only call of `to` against `state`, from the system caller, discarded.
fn view_at(state: &FixtureProvider, to: Address, data: Vec<u8>) -> Bytes {
    let mut evm = Context::mainnet()
        .modify_cfg_chained(|cfg| {
            cfg.chain_id = 1337;
            cfg.set_spec_and_mainnet_gas_params(SpecId::CANCUN)
        })
        .with_db(state.clone())
        .build_mainnet();
    let mut tx = TxEnv::new_system_tx_with_caller(SYSTEM_CALLER, to, data.into());
    tx.gas_limit = 30_000_000;
    evm.ctx_mut().set_tx(tx);
    let result = MainnetHandler::<_, revm::context_interface::result::EVMError<_>, _>::default()
        .run_system_call(&mut evm)
        .unwrap();
    assert!(result.is_success(), "{result:?}");
    result.output().cloned().unwrap_or_default()
}

fn health_of(state: &FixtureProvider) -> u8 {
    healthCall::abi_decode_returns(&view(state, healthCall {}.abi_encode())).unwrap()
}

/// The first word of `output(rid)`: the ABI offset of the dynamic struct, then its `state` word.
fn output_state(state: &FixtureProvider, rid: B256) -> u8 {
    let out = view(state, outputCall { resultId: rid }.abi_encode());
    out[63]
}

fn check_views(after: &FixtureProvider, s: &Scenario) {
    let e = &s.expect;
    assert_eq!(health_of(after), e.health, "{}: health", s.name);
    let cursor =
        recordCursorCall::abi_decode_returns(&view(after, recordCursorCall {}.abi_encode()))
            .unwrap();
    assert_eq!(cursor, e.cursor, "{}: cursor", s.name);
    assert_eq!(cursor, s.records.len() as u64, "{}: VR consumed the whole import", s.name);
    let open =
        openOutputCall::abi_decode_returns(&view(after, openOutputCall {}.abi_encode())).unwrap();
    assert_eq!(open, e.open_output, "{}: open output", s.name);
    let acked =
        lastAckedCall::abi_decode_returns(&view(after, lastAckedCall {}.abi_encode())).unwrap();
    assert_eq!(acked, e.last_acked, "{}: last acknowledged", s.name);
    let module = view(after, activeModuleCall {}.abi_encode());
    assert_eq!(Address::from_slice(&module[12..32]), e.active_module, "{}: module", s.name);
}

