/// The pinned code: the registry the genesis carries is the contracts-main `SealRegistry` ureth
/// pins, and the VR hashes the fixture carries are reported (VT-14 pins them).
#[test]
fn the_fixture_runs_contracts_main_bytecode() {
    use sha2::{Digest, Sha256};
    assert_eq!(
        B256::from_slice(&Sha256::digest(FIXTURE.as_bytes())),
        FIXTURE_SHA256,
        "testdata/vr-hook.json is not the copy of unicity-pos-contracts {FIXTURE_SOURCE}"
    );
    let genesis: serde_json::Value =
        serde_json::from_str(include_str!("../testdata/signed-beacon-genesis.json")).unwrap();
    let code: Bytes = genesis["alloc"]["0xff00000000000000000000000000000000000002"]["code"]
        .as_str()
        .unwrap()
        .parse()
        .unwrap();
    assert_eq!(keccak256(&code), SEAL_REGISTRY_CODE_HASH);
    println!("vr-hook: SealRegistry 0xff..02 runtime {SEAL_REGISTRY_CODE_HASH}");
    for a in &fixture().accounts {
        println!(
            "vr-hook: {:<16} {} runtime {} ({} bytes)",
            a.role,
            a.address,
            keccak256(&a.code),
            a.code.len()
        );
        assert!(a.code.len() <= 24_576, "{}: EIP-170", a.role);
    }
    for role in ["vr", "governanceFacet", "repairFacet", "recordsFacet", "poa", "composer"] {
        let a = account(role);
        let high = a.as_slice()[0];
        assert_eq!(high, 0xff, "{role} sits at its genesis address");
    }
    assert_eq!(account("vr"), VR);
}

/// Every scenario through the real block path: the block builds at the provisional pins with the
/// system budget at exactly the base plus the hook envelope, replays to itself, and leaves VR and
/// the modules in exactly the state forge computed; the hook reports forge's outcome.
#[test]
fn every_scenario_reproduces_forge_through_the_block_path() {
    let names: Vec<&str> = fixture().scenarios.iter().map(|s| s.name.as_str()).collect();
    assert_eq!(names, SCENARIOS, "exactly the generator's scenarios");
    for s in &fixture().scenarios {
        let world = World::new(s);
        let hook = pinned(s);
        let (built, after) = world
            .build(hook)
            .unwrap_or_else(|e| panic!("{}: the block must stay valid: {e}", s.name));
        let d = diff(&after, s);
        assert!(d.is_empty(), "{}: state differs from forge:\n{}", s.name, d.join("\n"));
        check_views(&after, s);
        let replay = replay_complete(
            &world.config(hook),
            world.provider.clone(),
            &world.provider,
            &built.outcome.block,
        )
        .unwrap_or_else(|e| panic!("{}: replay: {e}", s.name));
        assert_eq!(replay.output.result, built.outcome.execution_result, "{}", s.name);
        let receipts: Vec<bool> =
            built.outcome.execution_result.receipts.iter().map(|r| r.success).collect();
        let want: Vec<bool> = s.txs.iter().map(|t| t.success).collect();
        assert_eq!(receipts, want, "{}: the public transactions' statuses are forge's", s.name);

        // the same hook run directly reports forge's outcome and lands on the same state
        let (before, env) = world.before_hooks();
        let budget = hook.envelope_gas().unwrap();
        let (outcome, direct) = hooks_on(&before, &env, &hook, budget).unwrap();
        assert_eq!(outcome.applied, s.expect.applied, "{}: applied", s.name);
        assert_eq!(outcome.elected, Some(s.expect.outcome), "{}: elect outcome", s.name);
        assert!(diff_hooks(&direct, s).is_empty(), "{}: the direct run differs", s.name);
        assert!(outcome.gas_spent <= budget);
        // a node that pins no hook computes another state and refuses the block
        if !s.records.is_empty() || s.expect.outcome != 1 {
            assert!(
                replay_complete(
                    &world.config(RecordsHook::default()),
                    world.provider.clone(),
                    &world.provider,
                    &built.outcome.block
                )
                .is_err(),
                "{}",
                s.name
            );
        }
    }
}

/// Containment at the hook: every misbehaving module leaves a valid block, VR Faulted (or, for the
/// absorbed re-entry and the cap griefing, healthy) and the cursor advanced by exactly the batch.
#[test]
fn a_misbehaving_module_never_invalidates_the_block() {
    // (scenario, what the module does, elect outcome, health)
    let cases: &[(&str, &str, u8, u8)] = &[
        ("elect-revert", "elect reverts", 3, 1),
        ("elect-oog", "elect burns its whole cap", 3, 1),
        ("elect-malformed", "elect returns 65 malformed bytes", 3, 1),
        ("elect-huge", "elect returns 1 MiB of return data (refused before any copy)", 3, 1),
        ("elect-write-revert", "elect writes, then reverts", 3, 1),
        ("elect-reenter-bubble", "elect re-enters publish and bubbles the revert", 3, 1),
        (
            "elect-reenter",
            "elect makes 14 well-formed re-entrant calls (13 refused, the lock-exempt invalidate succeeds), then answers",
            2,
            0,
        ),
        ("elect-grief", "elect burns to 20,000 below its cap, then answers", 2, 0),
        ("output-malformed", "outputOf of a ready reservation is malformed", 3, 1),
        (
            "output-huge",
            "outputOf builds a 1 MiB return and runs out of gas (memory) in its own frame",
            3,
            1,
        ),
        (
            "output-oversize",
            "outputOf answers a 16-member Ready output one byte above the 5,408-byte cap",
            3,
            1,
        ),
        ("output-invalid", "outputOf serves a Ready output VR's validation rejects", 3, 1),
        ("records-revert", "onRecords reverts in the Ack + Boundary batch", 1, 1),
        ("records-oog", "onRecords burns its cap", 1, 1),
        (
            "records-huge",
            "onRecords builds a 1 MiB return and runs out of gas (memory) in its own frame",
            1,
            1,
        ),
        ("records-word", "onRecords (a void step) returns a word", 1, 1),
        ("records-reenter", "onRecords re-enters publish and bubbles", 1, 1),
        ("resolved-revert", "onResolved reverts at the Boundary", 1, 1),
        ("resolved-oog", "onResolved burns its cap", 1, 1),
        ("attach-revert", "the new module's attach reverts at the switch", 1, 1),
        (
            "batch32-exhausted",
            "onRecords of a full H = 32 batch exhausts its 48,000,000 cap",
            1,
            1,
        ),
    ];
    assert_eq!(cases.iter().filter(|c| c.3 == 1).count(), 19, "19 faults");
    assert_eq!(cases.iter().filter(|c| c.3 == 0).count(), 2, "2 absorbed, Healthy");
    for (name, what, outcome, health) in cases {
        let s = scenario(name);
        assert_eq!((s.expect.outcome, s.expect.health), (*outcome, *health), "{name}: forge");
        let world = World::new(s);
        let (built, after) = world
            .build(pinned(s))
            .unwrap_or_else(|e| panic!("{name} ({what}) invalidated the block: {e}"));
        assert!(diff(&after, s).is_empty(), "{name}");
        assert_eq!(health_of(&after), *health, "{name}: {what}");
        let (before, env) = world.before_hooks();
        let hook = pinned(s);
        let (o, _) = hooks_on(&before, &env, &hook, hook.envelope_gas().unwrap()).unwrap();
        assert_eq!(o.elected, Some(*outcome), "{name}");
        assert_eq!(o.applied, s.expect.applied, "{name}: the cursor moved by the batch");
        println!(
            "vr-hook: containment {name:<22} {what}: block valid, outcome {outcome}, health {health}, header gas {}",
            built.outcome.execution_result.gas_used
        );
    }
    // the write a reverting module made rolled back with its frame
    let s = scenario("elect-write-revert");
    let mock = account("mock");
    assert_eq!(
        s.pre.get(&mock).map(|p| p.len()),
        s.post.get(&mock).map(|p| p.len()),
        "the module's partial write is not in the post state"
    );
    // the re-entrant calls: register, proposeBinding and every locked mutator refused with Locked,
    // the hooks with NotSystemCaller, the steps with NotSelf, the lock-exempt invalidate succeeds
    let s = scenario("elect-reenter");
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    let mock = account("mock");
    assert_eq!(call(&after, mock, reentryAttemptsCall {}), U256::from(14));
    assert_eq!(call(&after, mock, reentryRefusalsCall {}), U256::from(13));
    let locked = alloy_primitives::FixedBytes(keccak256("Locked()")[..4].try_into().unwrap());
    let sys = alloy_primitives::FixedBytes(keccak256("NotSystemCaller()")[..4].try_into().unwrap());
    let self_ = alloy_primitives::FixedBytes(keccak256("NotSelf()")[..4].try_into().unwrap());
    let want = [
        locked,
        sys,
        sys,
        locked,
        locked,
        locked,
        locked,
        self_,
        self_,
        self_,
        self_,
        locked,
        locked,
        alloy_primitives::FixedBytes::ZERO,
    ];
    for (k, w) in want.iter().enumerate() {
        assert_eq!(call(&after, mock, reentryErrorsCall { k: U256::from(k) }), *w, "re-entry {k}");
    }
    // a fault left no reservation behind
    for name in ["elect-revert", "output-malformed", "output-invalid", "output-oversize"] {
        let s = scenario(name);
        let (_, after) = World::new(s).build(pinned(s)).unwrap();
        assert_eq!(output_state(&after, keccak256("R")), 0, "{name}: R was never reserved");
    }
}

/// Record kinds 6 to 8 apply through the hook: Boundary installs and activates, `OutputRejected`
/// rejects then `SessionClosed` closes (with `PoA` parking the joiner), `HolderRetirement` marks.
#[test]
fn record_kinds_six_to_eight_apply_through_the_hook() {
    let s = scenario("holder-batch");
    let kinds: Vec<u8> = s.records.iter().map(|r| r.kind).collect();
    assert_eq!(
        kinds,
        vec![2, 6, 8, 4, 8],
        "Ack, Boundary, HolderRetirement, Closure, HolderRetirement"
    );
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    for (id, generation) in [(2u64, 1u64), (3, 1)] {
        let out = view(&after, retiredCall { holder: 0, id, generation }.abi_encode());
        assert!(retiredCall::abi_decode_returns(&out).unwrap(), "({id}, {generation}) retired");
    }
    let out = view(&after, retiredCall { holder: 0, id: 4, generation: 1 }.abi_encode());
    assert!(!retiredCall::abi_decode_returns(&out).unwrap());
    assert_eq!(output_state(&after, keccak256("R")), 5, "R Acknowledged");
    assert_eq!(health_of(&after), 0, "no anomaly");

    let s = scenario("poa-rejected");
    let kinds: Vec<u8> = s.records.iter().map(|r| r.kind).collect();
    assert_eq!(kinds, vec![7, 1], "OutputRejected(Expired), SessionClosed");
    let (_, before) = World::new(s).build(RecordsHook::default()).unwrap();
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    let rid = B256::from(s.records[0].data[..32].try_into().map(|a: [u8; 32]| a).unwrap());
    assert_eq!(output_state(&before, rid), 2, "Published before the block");
    assert_eq!(output_state(&after, rid), 7, "Closed after it");
    assert_eq!(health_of(&after), 0);
    // the PoA module's state moved (the joiner parked): its storage changed in the block
    let poa = account("poa");
    assert_ne!(s.pre.get(&poa), s.post.get(&poa), "PoA saw the rejection");
}

/// The pointer switch through the hook: `PoA` to a fresh `PoA` instance at the Boundary, the old
/// module fed its records first; and a switch to a module whose attach fails leaves VR Faulted with
/// the pointer moved and no holder entry consumed.
#[test]
fn the_module_switch_works_through_the_hook() {
    let s = scenario("poa-switch");
    let (before, _) = World::new(s).before_hooks();
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    let module = |st: &FixtureProvider| {
        let out = view(st, activeModuleCall {}.abi_encode());
        Address::from_slice(&out[12..32])
    };
    assert_eq!(module(&before), account("poa"));
    assert_eq!(module(&after), account("poaNext"));
    assert_eq!(health_of(&after), 0);
    assert!(
        !s.pre.contains_key(&account("poaNext")) && s.post.contains_key(&account("poaNext")),
        "attach wrote the new module's committee"
    );

    let s = scenario("attach-revert");
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    assert_eq!(module(&after), account("mockNext"));
    assert_eq!(health_of(&after), 1, "Faulted: repair mode follows");
    let out = view(&after, holderCountCall {}.abi_encode());
    assert_eq!(holderCountCall::abi_decode_returns(&out).unwrap(), 0);
}

/// The smallest `g` in `(lo, hi]` for which `ok` holds (monotone), exactly.
fn threshold(mut lo: u64, mut hi: u64, ok: impl Fn(u64) -> bool) -> u64 {
    assert!(ok(hi), "not even {hi} suffices");
    assert!(!ok(lo), "{lo} already suffices");
    while hi - lo > 1 {
        let mid = lo + (hi - lo) / 2;
        if ok(mid) {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    hi
}

/// One scenario's hook gas: what the records step and the election spend at the pins, and the
/// smallest reservation of each at which the hook still reproduces forge (below it a contained
/// step is `BudgetShort` or VR runs out of gas).
struct HookGas {
    records_gas: u64,
    elect_gas: u64,
    min_records: u64,
    min_elect: u64,
}

/// Measures a scenario and checks it against the pins. The records threshold is searched with the
/// election off, from the state before the hooks; the election threshold from the state after the
/// records step (the hook then only reads the caught-up cursor before electing), so a search never
/// repeats the other step's work. Neither search can succeed below the gas the step spends at the
/// pins, which bounds it from below.
fn measure(s: &Scenario) -> HookGas {
    let world = World::new(s);
    let (before, env) = world.before_hooks();
    let n = s.expect.applied;
    let hook = pinned(s);
    let records_only = RecordsHook { election: Address::ZERO, elect_gas: 0, ..hook };
    let (r, after_records) =
        hooks_on(&before, &env, &records_only, records_only.envelope_gas().unwrap()).unwrap();
    let (both, _) = hooks_on(&before, &env, &hook, hook.envelope_gas().unwrap()).unwrap();
    let records_gas = r.gas_spent;
    let elect_gas = both.gas_spent - r.gas_spent;
    assert!(records_gas <= HOOK_READS_GAS + n.max(1) * HOOK_RECORD_GAS, "{}", s.name);
    assert!(records_gas <= HOOK_READS_GAS + u64::from(s.h) * HOOK_RECORD_GAS, "{}", s.name);
    assert!(elect_gas <= ELECT_GAS, "{}: elect {elect_gas}", s.name);

    let min_records = if n == 0 {
        0
    } else {
        let lands = |budget: u64| {
            hooks_on(&before, &env, &records_only, budget)
                .map(|(o, st)| {
                    o.applied == n &&
                        fixture().accounts.iter().all(|a| {
                            st.storage_of(a.address) == after_records.storage_of(a.address)
                        })
                })
                .unwrap_or(false)
        };
        // the requirement sits a few million above the spend (the contained steps' reserves); the
        // envelope bounds it in any case
        let envelope = records_only.envelope_gas().unwrap();
        let near = (records_gas + 4_000_000).min(envelope);
        threshold(records_gas - 1, if lands(near) { near } else { envelope }, lands)
    };
    let (reads, _) = hooks_on(&after_records, &env, &records_only, HOOK_READS_GAS).unwrap();
    let min_elect = threshold(elect_gas.saturating_sub(1), ELECT_GAS, |g| {
        let h = RecordsHook { elect_gas: g, ..hook };
        hooks_on(&after_records, &env, &h, reads.gas_spent + g)
            .map(|(o, st)| o.elected == Some(s.expect.outcome) && diff_hooks(&st, s).is_empty())
            .unwrap_or(false)
    });
    assert!(min_records <= HOOK_READS_GAS + n * HOOK_RECORD_GAS, "{}", s.name);
    assert!(n == 0 || min_records.div_ceil(n) <= RECORD_REQUIREMENT, "{}: {min_records}", s.name);
    assert!(min_elect <= ELECT_REQUIREMENT, "{}: {min_elect}", s.name);
    assert!(min_elect <= ELECT_GAS, "{}", s.name);
    println!(
        "vr-hook: {:<22} {:>3} {:>10} {:>10} {:>11} {:>11}",
        s.name, n, records_gas, elect_gas, min_records, min_elect
    );
    HookGas { records_gas, elect_gas, min_records, min_elect }
}

/// Which gas test measures a scenario. The groups split the measurement so each test fits CI's
/// per-test limit; together they cover every scenario exactly once.
fn gas_group(s: &Scenario) -> &'static str {
    match s.name.as_str() {
        "batch32-max" => "h32-healthy",
        "batch32-exhausted" => "h32-exhausted",
        "elect-max" => "max-election",
        "switch-max" => "max-switch",
        name if COMBINED.contains(&name) => "combined",
        _ if s.expect.applied == 0 => "elections",
        _ => "record-batches",
    }
}

fn measure_group(group: &str) -> Vec<(&'static Scenario, HookGas)> {
    println!(
        "vr-hook: provisional pins: ElectGas {ELECT_GAS} = ceil(5/4 x max(analytical {ELECT_ANALYTICAL}, measured {ELECT_REQUIREMENT})), HookRecordGas {HOOK_RECORD_GAS} = ceil(5/4 x max(analytical {RECORD_ANALYTICAL}, measured {RECORD_REQUIREMENT}))"
    );
    println!(
        "vr-hook: {:<22} {:>3} {:>10} {:>10} {:>11} {:>11}",
        "scenario", "n", "records", "elect", "min records", "min elect"
    );
    let all: Vec<_> = fixture()
        .scenarios
        .iter()
        .filter(|s| gas_group(s) == group)
        .map(|s| (s, measure(s)))
        .collect();
    assert!(!all.is_empty(), "{group}");
    all
}

/// Gas against the provisional pins for every scenario, in six groups: each scenario's records
/// and election cost on the hook's own meter, and the smallest reservations that still reproduce
/// forge, all within `HookRecordGas` per record and `ElectGas`.
#[test]
fn hook_gas_groups_cover_every_scenario() {
    let groups = [
        "elections",
        "record-batches",
        "h32-healthy",
        "h32-exhausted",
        "max-election",
        "max-switch",
        "combined",
    ];
    for s in &fixture().scenarios {
        assert!(groups.contains(&gas_group(s)), "{}", s.name);
    }
    let elections = fixture().scenarios.iter().filter(|s| gas_group(s) == "elections").count();
    let batches = fixture().scenarios.iter().filter(|s| gas_group(s) == "record-batches").count();
    assert_eq!(elections + batches + 4 + COMBINED.len(), SCENARIOS.len());
}

#[test]
fn hook_gas_elections_within_the_pins() {
    let all = measure_group("elections");
    let (s, worst) = all.iter().max_by_key(|(_, g)| g.min_elect).unwrap();
    println!(
        "vr-hook: worst min elect {} ({}) against ElectGas {ELECT_GAS}",
        worst.min_elect, s.name
    );
}

#[test]
fn hook_gas_record_batches_within_the_pins() {
    let all = measure_group("record-batches");
    let (s, worst) =
        all.iter().max_by_key(|(s, g)| g.min_records.div_ceil(s.expect.applied)).unwrap();
    println!(
        "vr-hook: worst min records per record {} ({}) against HookRecordGas {HOOK_RECORD_GAS}",
        worst.min_records.div_ceil(s.expect.applied),
        s.name
    );
}

/// H = 32 at the maximum record cap, a healthy delivery burning its 48 M cap.
#[test]
fn hook_gas_full_h32_batch_at_the_maximum_record_cap() {
    let [(s, g)] = measure_group("h32-healthy").try_into().ok().unwrap();
    assert_eq!((s.h, s.expect.applied), (32, 32));
    println!(
        "vr-hook: max H=32 batch, onRecords at 32 x 1,500,000: records gas {}, min budget {} ({} per record) against H x HookRecordGas {}",
        g.records_gas,
        g.min_records,
        g.min_records / 32,
        32 * HOOK_RECORD_GAS
    );
    assert!(g.min_records <= HOOK_READS_GAS + 32 * HOOK_RECORD_GAS);
    assert_eq!(g.min_records, BATCH_REQUIREMENT, "the recorded R_32 is this measurement");
}

/// The same batch with onRecords exhausting its cap.
#[test]
fn hook_gas_full_h32_batch_with_an_exhausted_callback() {
    let [(_, g)] = measure_group("h32-exhausted").try_into().ok().unwrap();
    println!(
        "vr-hook: max H=32 batch, onRecords exhausting its cap: records gas {}, min budget {}",
        g.records_gas, g.min_records
    );
    assert!(g.min_records <= HOOK_READS_GAS + 32 * HOOK_RECORD_GAS);
}

/// The compound election at the maximum caps: its complete requirement exceeds the contained step
/// alone and is the recorded one.
#[test]
fn hook_gas_compound_election_at_the_maximum_caps() {
    let [(_, g)] = measure_group("max-election").try_into().ok().unwrap();
    println!(
        "vr-hook: max compound election (caps 4,000,000 + 1,000,000, 16 members, 16 changes, 64 KiB): elect gas {}, min ElectGas {} against ElectGas {ELECT_GAS} (cap-based step {ELECT_ANALYTICAL})",
        g.elect_gas, g.min_elect
    );
    assert_eq!(g.min_elect, ELECT_REQUIREMENT, "the recorded requirement is this measurement");
    assert!(g.min_elect > ELECT_ANALYTICAL, "the step alone is not the whole requirement");
}

/// The 16-member switching Boundary at the maximum caps, delivered alone: its requirement is the
/// recorded per-record one, above the small-payload analytical figure.
#[test]
fn hook_gas_switching_boundary_alone_at_the_maximum_caps() {
    let [(_, g)] = measure_group("max-switch").try_into().ok().unwrap();
    println!(
        "vr-hook: max switching Boundary alone (16 installed, 15 activated, 64 KiB, callbacks at 500,000 / 1,000,000 / 1,500,000 / 500,000 / 3,000,000): records gas {}, min budget {} against HookRecordGas {HOOK_RECORD_GAS} (analytical {RECORD_ANALYTICAL})",
        g.records_gas, g.min_records
    );
    assert_eq!(g.min_records, RECORD_REQUIREMENT, "the recorded requirement is this measurement");
    assert!(g.min_records > RECORD_ANALYTICAL, "the small-payload analytical figure is too low");
    assert!(g.min_records <= HOOK_READS_GAS + HOOK_RECORD_GAS);
}

/// An election priced below the contained step's requirement but above VR's own pre-step work: VR
/// reports `BudgetShort` and answers Disabled (no reservation, no fault), and the block stays
/// valid. A due election is then skipped, so such a pin is an acceptance failure. Below VR's own
/// pre-step work (here 1 gas) the hook runs out of gas and the block is invalid: the pin must cover
/// the whole cap-based requirement, never only the measured spend.
#[test]
fn an_election_priced_below_the_step_budget_is_disabled_not_invalid() {
    let s = scenario("poa-elect");
    let world = World::new(s);
    let (before, env) = world.before_hooks();
    let hook = RecordsHook { elect_gas: 2_000_000, ..pinned(s) };
    let (o, after) = hooks_on(&before, &env, &hook, hook.envelope_gas().unwrap()).unwrap();
    assert_eq!(o.elected, Some(0), "BudgetShort: Disabled");
    assert_eq!(health_of(&after), 0, "no fault for a short budget");
    let open =
        openOutputCall::abi_decode_returns(&view(&after, openOutputCall {}.abi_encode())).unwrap();
    assert_eq!(open, B256::ZERO);
    assert!(world.build(hook).is_ok(), "the block stays valid");
    let starved = RecordsHook { elect_gas: 1, ..pinned(s) };
    assert!(world.build(starved).is_err(), "an ElectGas below VR's own work invalidates the block");
}

/// The maximum compound paths at VR's maximum accepted caps (design 3.3.4), each through the real
/// block path: callbacks ran with the right content and the module stayed Healthy where they
/// answered; the cursor moved by exactly the batch, the failing frame rolled back and the module
/// was Faulted where one exhausted its cap. Their gas is measured by the `hook_gas_*` tests.
#[test]
fn the_maximum_compound_paths_run_as_forge_computed() {
    let mock = account("mock");
    let next = account("mockNext");
    let r = keccak256("R");
    // H = 32 at the maximum record cap, a healthy delivery burning its 48 M cap
    let s = scenario("batch32-max");
    assert_eq!((s.h, s.records.len(), s.expect.applied), (32, 32, 32));
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    assert_eq!(health_of(&after), 0);
    assert_eq!(module_log(&after, mock), ["onResolved:1", "onRecords:0:32", "elect"]);
    assert_eq!(output_state(&after, r), 5, "R Acknowledged");

    // the same batch with onRecords exhausting its cap: applied, rolled back, Faulted
    let s = scenario("batch32-exhausted");
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    assert_eq!(health_of(&after), 1);
    assert_eq!(module_log(&after, mock), ["onResolved:1"], "the onRecords frame rolled back");
    assert_eq!(output_state(&after, r), 5, "the records applied regardless");
    let cursor = call(&after, VR, recordCursorCall {});
    assert_eq!(cursor, 32);

    // the compound election at the maximum caps: 16 members, 16 bound changes (64 KiB of payloads)
    let s = scenario("elect-max");
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    assert_eq!(health_of(&after), 0);
    assert_eq!(output_state(&after, r), 2, "R Published");
    assert_eq!(module_log(&after, mock).last().map(String::as_str), Some("elect"));

    // the 16-member switching Boundary at the maximum caps, delivered a block after its Ack
    let s = scenario("switch-max");
    assert_eq!(s.records.iter().map(|r| r.kind).collect::<Vec<_>>(), [2, 6]);
    assert_eq!((s.expect.applied, s.expect.cursor), (1, 2), "the Boundary alone in this block");
    let (before, _) = World::new(s).before_hooks();
    assert_eq!(call(&before, VR, recordCursorCall {}), 1, "the Ack was applied a block earlier");
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    assert_eq!(health_of(&after), 0);
    assert_eq!(Address::from_slice(&view(&after, activeModuleCall {}.abi_encode())[12..32]), next);
    assert_eq!(module_log(&after, mock), ["onResolved:1", "onRecords:1:1", "detach"]);
    assert_eq!(module_log(&after, next).first().map(String::as_str), Some("attach"));
    assert_eq!(call(&after, next, attachMembersCall {}), U256::from(16));
    assert_eq!(call(&after, next, attachPreviousCall {}), mock);
    assert_eq!(call(&after, VR, holderCountCall {}), 1);
}

/// Fault attribution through public transactions after the hooks (design 11, VT-02): the hook
/// reserves an asynchronous output; then 100 early publishes in one transaction (each Pending, the
/// lock taken and cleared each time), a publish with too little gas (`BudgetShort`, reverted), the
/// module turning Ready, and one transaction with a short publish refused inside it followed by a
/// funded one that publishes. VR stays Healthy throughout.
#[test]
fn early_short_and_reused_publishes_are_not_faults() {
    let s = scenario("publish-trace");
    assert_eq!(s.txs.len(), 4);
    let world = World::new(s);
    let (built, after) = world.build(pinned(s)).unwrap();
    let receipts: Vec<bool> =
        built.outcome.execution_result.receipts.iter().map(|r| r.success).collect();
    assert_eq!(receipts, [true, false, true, true]);
    let driver = account("publishDriver");
    assert_eq!(call(&after, driver, pendingSeenCall {}), U256::from(100));
    assert!(call(&after, driver, shortRefusedCall {}));
    assert!(call(&after, driver, publishedCall {}));
    assert_eq!(output_state(&after, keccak256("R")), 2, "R Published");
    assert_eq!(health_of(&after), 0, "no early, short or refused publish is a fault");
    // after the hooks alone, R is Reserved and unpublished
    let (_, hooks_only) = world.build_with(pinned(s), vec![]).unwrap();
    assert!(diff_hooks(&hooks_only, s).is_empty());
    assert_eq!(output_state(&hooks_only, keccak256("R")), 1, "R Reserved");
    for (i, r) in built.outcome.execution_result.receipts.iter().enumerate() {
        println!(
            "vr-hook: publish trace tx {i}: success {} cumulative gas {}",
            r.success, r.cumulative_gas_used
        );
    }
}

/// The combined fixtures at the VR batch rule (VT-14 acceptance; astra urethhook r2): one H = 32
/// records call with a 16-member, 64 KiB switching output's Ack, 30 ordinary records and its
/// Boundary, both modules' record callbacks and every switch callback at their maximum caps. The
/// old module's segment runs through the Boundary, the new one gets the rest, VR stays Healthy, and
/// each needs no more than `M_32 = R_32 + B` of reservation.
#[test]
fn hook_gas_combined_switch_and_ordinary_records_fit_the_batch_allowance() {
    let all = measure_group("combined");
    assert_eq!(all.len(), COMBINED.len());
    for (s, g) in &all {
        assert_eq!((s.h, s.expect.applied), (32, 32), "{}", s.name);
        println!(
            "vr-hook: combined {:<13} records gas {:>10}, min budget {:>10} against M_32 {BATCH_ALLOWANCE_REQUIREMENT} and the allowance {}",
            s.name,
            g.records_gas,
            g.min_records,
            32 * VR_HOOK_RECORD_GAS
        );
        assert!(g.min_records <= BATCH_ALLOWANCE_REQUIREMENT, "{}: M_32 must cover it", s.name);
    }
}

/// Every scenario under the VR profile's batch pins (`HookRecordGas` = 2,743,763 at H = 32, the
/// amortized 87,800,416 allowance): the block builds with the system budget at exactly the hook
/// envelope (97,927,220), replays to itself and reaches forge's state, the combined fixtures
/// included; and each combined fixture lands on its reference state with a records-only
/// reservation of exactly `M_32`.
#[test]
fn every_scenario_runs_with_the_vr_batch_pins() {
    assert_eq!(VR_HOOK_RECORD_GAS, 2_743_763);
    assert_eq!(32 * VR_HOOK_RECORD_GAS, 87_800_416);
    assert_eq!(pin(BATCH_ALLOWANCE_REQUIREMENT), 87_800_410);
    assert_eq!(ELECT_GAS, 9_976_804);
    let mock = account("mock");
    let next = account("mockNext");
    for s in &fixture().scenarios {
        assert_eq!(s.h, 32);
        let world = World::new(s);
        let hook = RecordsHook { record_gas: VR_HOOK_RECORD_GAS, ..pinned(s) };
        assert_eq!(hook.envelope_gas().unwrap(), 97_927_220);
        let (built, after) = world.build(hook).unwrap_or_else(|e| {
            panic!("{}: the block must stay valid at the VR pins: {e}", s.name)
        });
        let d = diff(&after, s);
        assert!(d.is_empty(), "{}: state differs from forge:\n{}", s.name, d.join("\n"));
        check_views(&after, s);
        let replay = replay_complete(
            &world.config(hook),
            world.provider.clone(),
            &world.provider,
            &built.outcome.block,
        )
        .unwrap();
        assert_eq!(replay.output.result, built.outcome.execution_result, "{}", s.name);
        if let Some(at) = COMBINED.iter().position(|c| *c == s.name) {
            let before_boundary = [0u64, 15, 30][at];
            assert_eq!(health_of(&after), 0, "{}", s.name);
            assert_eq!(
                Address::from_slice(&view(&after, activeModuleCall {}.abi_encode())[12..32]),
                next
            );
            let old = module_log(&after, mock);
            assert_eq!(
                old[..2],
                ["onResolved:1".to_string(), format!("onRecords:0:{}", before_boundary + 2)]
            );
            assert_eq!(old[2], "detach");
            let new = module_log(&after, next);
            assert_eq!(new[0], "attach");
            if before_boundary < 30 {
                assert_eq!(
                    new[1],
                    format!("onRecords:{}:{}", before_boundary + 2, 30 - before_boundary)
                );
            }
            let (before, env) = world.before_hooks();
            let records = RecordsHook { election: Address::ZERO, elect_gas: 0, ..hook };
            let (_, reference) =
                hooks_on(&before, &env, &records, records.envelope_gas().unwrap()).unwrap();
            let (out, st) = hooks_on(&before, &env, &records, BATCH_ALLOWANCE_REQUIREMENT).unwrap();
            assert_eq!(out.applied, 32, "{}", s.name);
            assert_eq!(health_of(&st), 0, "{}", s.name);
            for a in &fixture().accounts {
                assert_eq!(
                    st.storage_of(a.address),
                    reference.storage_of(a.address),
                    "{}: {} at a reservation of M_32",
                    s.name,
                    a.role
                );
            }
        }
    }
}

/// The fresh complete-path measurement VT-14's genesis plan records (bft-core b1state
/// `VRHookMeasurement`, checked by `CheckVRHookGas`): `R_32`, B, the three combined fixtures and
/// the largest election requirement, with the code they were taken over and the caps and ceilings
/// they were taken at. Not part of the default run (it repeats the gas groups' searches); the
/// genesis plan runs it explicitly (`VR_HOOK_MEASUREMENT` names the output file):
///
/// ```text
/// cargo test -p reth-unicity-execution --features test-utils --test vr_hook -- \
///     --ignored --exact vr_hook_measurement
/// ```
#[test]
#[ignore = "the genesis plan's fresh measurement; run explicitly"]
fn vr_hook_measurement() {
    use sha2::{Digest, Sha256};
    let min_records = |name: &str| measure(scenario(name)).min_records;
    let records = min_records("batch32-max");
    let boundary = min_records("switch-max");
    let combined: Vec<_> = COMBINED
        .iter()
        .map(|c| serde_json::json!({"name": c, "records": 32, "reservation": min_records(c)}))
        .collect();
    let elect = ["elect-max", "native-worst", "poa-elect-16", "poa-elect-search"]
        .iter()
        .map(|n| measure(scenario(n)).min_elect)
        .max()
        .unwrap();
    let code = |role: &str| {
        let a = fixture().accounts.iter().find(|a| a.role == role).unwrap();
        format!("{}", keccak256(&a.code))
    };
    // VT-04: a generation whose module is not PoaElection (the PoS prototype's adapter) names its module's runtime hash. Every module
    // path of the measurement runs the cap-bounded test module (`elect-max`, `batch32-max`, `switch-max`), which is the most VR accepts
    // from any module whose declared gas bounds are within VR's caps; the PoA election scenarios stay in the maximum as extra cases. The
    // source line records the override so a reader of the file sees which module the hash names.
    let module_override = std::env::var("VR_HOOK_MODULE_CODE_HASH").ok();
    let module_hash = module_override.clone().unwrap_or_else(|| code("poa"));
    let caps = serde_json::json!({
        "elect": CAP_ELECT, "output": CAP_OUTPUT, "record": CAP_RECORD, "resolved": CAP_RESOLVED,
        "attach": CAP_ATTACH, "detach": CAP_DETACH, "gov": 1_000_000u64, "adopt": CAP_ADOPT,
    });
    let ceilings: serde_json::Map<String, serde_json::Value> =
        CEILINGS.iter().map(|(k, v)| (k.to_string(), (*v).into())).collect();
    let doc = serde_json::json!({
        "invariant": "vr-v1-single-live-output",
        "h": 32,
        "registry": format!("{VR}").to_lowercase(),
        "registryCodeHash": code("vr"),
        "moduleCodeHash": module_hash.clone(),
        "caps": caps,
        "ceilings": ceilings,
        "records": records,
        "boundary": boundary,
        "combined": combined,
        "elect": elect,
        "source": format!(
            "ureth tests/vr_hook.rs over testdata/vr-hook.json sha256 {} ({FIXTURE_SOURCE}){}",
            B256::from_slice(&Sha256::digest(FIXTURE.as_bytes())),
            match &module_override {
                Some(h) => format!("; module code hash {h} supplied by VR_HOOK_MODULE_CODE_HASH (cap-bounded module paths)"),
                None => String::new(),
            }
        ),
    });
    let text = serde_json::to_string_pretty(&doc).unwrap() + "\n";
    println!("{text}");
    if let Ok(path) = std::env::var("VR_HOOK_MEASUREMENT") {
        std::fs::write(&path, &text).unwrap();
        println!("vr-hook: wrote the measurement to {path}");
    }
}
